  function createActivityEmojiIcon(iconId) {
    const wrap = document.createElement("span");
    wrap.className = "activity-emoji-icon";
    wrap.setAttribute("data-card-meta", iconId);
    wrap.setAttribute("aria-hidden", "true");

    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("class", "activity-meta-icon");
    svg.setAttribute("width", "20");
    svg.setAttribute("height", "20");
    svg.setAttribute("focusable", "false");

    const use = document.createElementNS("http://www.w3.org/2000/svg", "use");
    const href = cardMetaIconHref(iconId);
    use.setAttribute("href", href);
    use.setAttributeNS("http://www.w3.org/1999/xlink", "href", href);
    svg.appendChild(use);
    wrap.appendChild(svg);
    return wrap;
  }

  function findEmojiIconId(text) {
    const raw = String(text || "");
    if (!raw) return null;
    const trimmed = raw.trim();
    const match = activityEmojiIconMap.find(([emoji]) => trimmed === emoji || trimmed.startsWith(emoji));
    return match ? match[1] : null;
  }

  function mountExperienceStepEmojiIcons(root = document) {
    const scope = root && typeof root.querySelectorAll === "function" ? root : document;
    scope.querySelectorAll(".experience-steps .liebres-step-item, .experience-steps > ul > li").forEach((li) => {
      if (li.querySelector(".activity-emoji-icon")) return;
      for (const node of Array.from(li.childNodes)) {
        if (node.nodeType !== Node.TEXT_NODE) continue;
        const iconId = findEmojiIconId(node.textContent);
        if (!iconId) continue;
        node.replaceWith(createActivityEmojiIcon(iconId));
        break;
      }
    });
  }

  var applyingPageIcons = false;
  var activityEmojiObserverStarted = false;
  var activityEmojiObserver = null;

  function sacramentoApplyPageIcons(root = document) {
    if (applyingPageIcons) return Promise.resolve();
    applyingPageIcons = true;

    const scope = root && typeof root.querySelectorAll === "function" ? root : document;
    const apply = () => {
      try {
        mountCardMetaIcons(scope);
        decorateActivityEmojiIcons(scope);
        mountExperienceStepEmojiIcons(scope);
        cleanCardMetaEmojiText(scope);
      } finally {
        applyingPageIcons = false;
      }
    };

    return ensureCardMetaSprite().then(apply).catch(apply);
  }

  function initHomeCardMetaIcons() {
    const root = document.getElementById("experiences") || document;
    sacramentoApplyPageIcons(root);
  }

  function decorateActivityEmojiIcons(root = document.body) {
    if (!root) return;
    const skipSelector = "script, style, textarea, option, svg, .activity-emoji-icon";
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        if (!node.nodeValue || !activityEmojiIconMap.some(([emoji]) => node.nodeValue.includes(emoji))) {
          return NodeFilter.FILTER_REJECT;
        }
        const parent = node.parentElement;
        if (!parent || parent.closest(skipSelector)) return NodeFilter.FILTER_REJECT;
        if (
          parent.closest(".card-meta-line .card-meta__text") &&
          parent.closest("[data-card-meta]")?.querySelector(".sprite-row svg")
        ) {
          return NodeFilter.FILTER_REJECT;
        }
        return NodeFilter.FILTER_ACCEPT;
      }
    });

    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);

    nodes.forEach(node => {
      const text = node.nodeValue;
      const fragment = document.createDocumentFragment();
      let i = 0;
      let changed = false;

      while (i < text.length) {
        const match = activityEmojiIconMap.find(([emoji]) => text.startsWith(emoji, i));
        if (match) {
          fragment.appendChild(createActivityEmojiIcon(match[1]));
          i += match[0].length;
          changed = true;
        } else {
          const next = activityEmojiIconMap
            .map(([emoji]) => {
              const index = text.indexOf(emoji, i + 1);
              return index === -1 ? text.length : index;
            })
            .reduce((min, index) => Math.min(min, index), text.length);
          fragment.appendChild(document.createTextNode(text.slice(i, next)));
          i = next;
        }
      }

      if (changed) node.replaceWith(fragment);
    });
  }

  var activityEmojiDecorateQueued = false;

  function queueDecorateActivityEmojiIcons() {
    if (applyingPageIcons || activityEmojiDecorateQueued) return;
    activityEmojiDecorateQueued = true;
    window.requestAnimationFrame(() => {
      activityEmojiDecorateQueued = false;
      if (applyingPageIcons) return;
      void sacramentoApplyPageIcons(document);
    });
  }

  function startActivityEmojiIconObserver() {
    if (activityEmojiObserverStarted || !document.body) return;
    activityEmojiObserverStarted = true;
    activityEmojiObserver = new MutationObserver((records) => {
      if (applyingPageIcons) return;
      const shouldRefresh = records.some((record) => {
        if (record.type === "characterData") return false;
        return Array.from(record.addedNodes || []).some((node) => {
          if (node.nodeType !== Node.ELEMENT_NODE) return false;
          return (
            node.matches?.("[data-translate], [data-translate-html], .liebres-step-item, [data-card-meta]") ||
            node.querySelector?.("[data-translate], [data-translate-html], .liebres-step-item, [data-card-meta]")
          );
        });
      });
      if (shouldRefresh) queueDecorateActivityEmojiIcons();
    });
    activityEmojiObserver.observe(document.body, {
      childList: true,
      subtree: true
    });
  }

  function getCardSeeMoreLabel(expanded, lang) {
    const language =
      lang ||
      (typeof window.getStoredLanguage === "function" && window.getStoredLanguage()) ||
      getInitialLanguage();
    const dict = translations[language] || translations.en;
    const key = expanded ? "historic_see_less" : "historic_see_more";
    return dict[key] || translations.en[key] || (expanded ? "See less" : "See more");
  }

  function refreshCardSeeMoreLabels(root = document) {
    root.querySelectorAll(".card .see-more").forEach((btn) => {
      const text = btn.closest(".card")?.querySelector(".card-description");
      const expanded = Boolean(text?.classList.contains("expanded"));
      btn.textContent = getCardSeeMoreLabel(expanded);
    });
  }

  function cardDescriptionNeedsClamp(text) {
    if (!text) return false;
    const wasExpanded = text.classList.contains("expanded");
    if (wasExpanded) text.classList.remove("expanded");
    const needsClamp = text.scrollHeight > text.clientHeight + 5;
    if (wasExpanded) text.classList.add("expanded");
    return needsClamp;
  }

  function updateCardSeeMoreVisibility(card) {
    const text = card.querySelector(".card-description");
    const btn = card.querySelector(".see-more");
    if (!text || !btn) return;

    const needsClamp = cardDescriptionNeedsClamp(text);
    if (!needsClamp) {
      text.classList.remove("expanded");
      btn.style.display = "none";
      return;
    }

    btn.style.removeProperty("display");
  }

  function initCardSeeMoreToggles(root = document) {
    root.querySelectorAll(".card:not(.card--category-modal)").forEach((card) => {
      const text = card.querySelector(".card-description");
      const btn = card.querySelector(".see-more");
      if (!text || !btn) return;

      if (btn.dataset.seeMoreBound !== "1") {
        btn.dataset.seeMoreBound = "1";
        btn.setAttribute("role", "button");
        btn.setAttribute("tabindex", "0");

        btn.addEventListener("click", () => {
          const expanded = text.classList.toggle("expanded");
          btn.textContent = getCardSeeMoreLabel(expanded);
          updateCardSeeMoreVisibility(card);
        });

        btn.addEventListener("keydown", (e) => {
          if (e.key !== "Enter" && e.key !== " ") return;
          e.preventDefault();
          btn.click();
        });
      }

      updateCardSeeMoreVisibility(card);
    });

    refreshCardSeeMoreLabels(root);
  }

  function scheduleCardSeeMoreRefresh(root = document) {
    const scope = root && typeof root.querySelectorAll === "function" ? root : document;
    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(() => {
        initCardSeeMoreToggles(scope);
      });
    });
  }

  function cleanCardMetaEmojiText(root = document) {
    const scope = root && typeof root.querySelectorAll === "function" ? root : document;
    const leadingEmoji =
      /^[\s\uFE0F\u200D⭐🍷🧉✔✅🔥🚤📍🏛🚶📸🌅🍽🌐🛡🌍🌶🕯🇪🇸🇧🇷🍺🍸💃🐎🌿🍇]+/u;

    scope.querySelectorAll(".card [data-card-meta] .card-meta__text").forEach((el) => {
      const line = el.closest("[data-card-meta]");
      if (!line?.querySelector(".sprite-row svg")) return;
      el.querySelectorAll(".activity-emoji-icon").forEach((node) => node.remove());
      const value = el.textContent || "";
      const cleaned = value.replace(leadingEmoji, "").trimStart();
      if (cleaned !== value) el.textContent = cleaned;
    });
  }

  window.sacramentoGetCardSeeMoreLabel = getCardSeeMoreLabel;
  window.sacramentoRefreshCardSeeMoreLabels = refreshCardSeeMoreLabels;
  window.sacramentoInitCardSeeMore = initCardSeeMoreToggles;

  function setLanguage(language) {
  
    if (!translations[language]) language = "en";
  
    document.querySelectorAll("[data-translate-html]").forEach((el) => {
      if (el.hasAttribute("data-i18n-skip") || el.closest("[data-i18n-skip]")) return;
      const key = el.dataset.translateHtml;
      const dict = translations[language];
      if (dict && Object.prototype.hasOwnProperty.call(dict, key)) {
        el.innerHTML = dict[key];
      }
    });

    document.querySelectorAll("[data-translate]").forEach(el => {
      if (el.hasAttribute("data-i18n-skip") || el.closest("[data-i18n-skip]")) return;
      const key = el.dataset.translate;
      const dict = translations[language];
      if (dict && Object.prototype.hasOwnProperty.call(dict, key)) {
        el.textContent = dict[key];
      }
    });

    document.querySelectorAll("[data-translate-title]").forEach(el => {
      const key = el.dataset.translateTitle;
      const dict = translations[language];
      if (dict && Object.prototype.hasOwnProperty.call(dict, key)) {
        el.setAttribute("title", dict[key]);
      }
    });

    document.querySelectorAll("[data-translate-aria-label]").forEach(el => {
      const key = el.dataset.translateAriaLabel;
      const dict = translations[language];
      if (dict && Object.prototype.hasOwnProperty.call(dict, key)) {
        el.setAttribute("aria-label", dict[key]);
      }
    });

    document.querySelectorAll("[data-translate-alt]").forEach(el => {
      const key = el.dataset.translateAlt;
      const dict = translations[language];
      if (dict && Object.prototype.hasOwnProperty.call(dict, key)) {
        el.setAttribute("alt", dict[key]);
      }
    });

    document.querySelectorAll("[data-translate-placeholder]").forEach((el) => {
      const key = el.dataset.translatePlaceholder;
      const dict = translations[language];
      if (dict && Object.prototype.hasOwnProperty.call(dict, key) && "placeholder" in el) {
        el.setAttribute("placeholder", dict[key]);
      }
    });

    const guidedHelpText = document.getElementById("rentGuidedHelpText");
    if (guidedHelpText) {
      const selectedType =
        document.querySelector('#rentPopupOverlay input[name="rentType"]:checked')?.value || "cart";
      const guidedKey = selectedType === "cart6" ? "rent_guided_help_text_cart6" : "rent_guided_help_text_cart";
      guidedHelpText.textContent =
        translations[language][guidedKey] || translations.en[guidedKey] || guidedHelpText.textContent;
    }

    localStorage.setItem("selectedLanguage", language);
    window.__SACRAMENTO_ACTIVE_LANG__ = language;
    document.documentElement.lang = language;

    document.querySelectorAll(".lang-btn").forEach(btn => {
      btn.classList.toggle("active", btn.dataset.lang === language);
    });

    document.dispatchEvent(new CustomEvent("sacramento:setLanguage", { detail: { language } }));

    if (typeof window.sacramentoInitWhatsAppFloatLinks === "function") {
      window.sacramentoInitWhatsAppFloatLinks();
    }

    if (typeof window.sacramentoRenderWalkingPriceBadges === "function") {
      window.sacramentoRenderWalkingPriceBadges();
    }
  
    sacramentoApplyPageIcons();
    refreshCardSeeMoreLabels();
    scheduleCardSeeMoreRefresh();
    window.requestAnimationFrame(() => {
      sacramentoApplyPageIcons();
    });
  }

  window.sacramentoSetLanguage = setLanguage;
  window.sacramentoMountCardMetaIcons = mountCardMetaIcons;
  window.sacramentoDecorateActivityEmojiIcons = decorateActivityEmojiIcons;
  window.sacramentoMountExperienceStepEmojiIcons = mountExperienceStepEmojiIcons;
  window.sacramentoInitHomeCardMetaIcons = initHomeCardMetaIcons;

  const CARD_SOON_EXPLORE_SELECTOR =
    "#homeLupajackExploreBtn, #homeMateAsadoExploreBtn";

  function getCardExperiencePageUrl(card) {
    const buttons = card.querySelector(".card-buttons");
    if (!buttons) return null;

    const explore = buttons.querySelector(".btn:not(.secondary)");
    if (explore?.tagName === "A") {
      const href = explore.getAttribute("href")?.trim();
      if (href && href !== "#" && !href.startsWith("javascript:")) return href;
    }

    const reserve = buttons.querySelector("a.btn.secondary");
    const reserveHref = reserve?.getAttribute("href")?.trim();
    if (reserveHref && reserveHref !== "#" && !reserveHref.startsWith("javascript:")) {
      return reserveHref.split("#")[0];
    }

    return null;
  }

  function sacramentoInitCardReserveButtons(root = document) {
    root.querySelectorAll(".card").forEach((card) => {
      const reserve = card.querySelector(".card-buttons a.btn.secondary");
      if (!reserve || reserve.dataset.sacReserveBound === "1") return;
      reserve.dataset.sacReserveBound = "1";

      reserve.addEventListener("click", (e) => {
        e.preventDefault();
        e.stopPropagation();

        if (card.querySelector(CARD_SOON_EXPLORE_SELECTOR)) {
          openHomeLupajackSoonPopup();
          return;
        }

        const pageHref = getCardExperiencePageUrl(card);
        if (!pageHref) return;

        const dest = new URL(pageHref, window.location.href);
        dest.hash = "reservar";
        window.location.assign(dest.href);
      });
    });
  }

  window.sacramentoInitCardReserveButtons = sacramentoInitCardReserveButtons;

  function openHomeLupajackSoonPopup() {
    const overlay = document.getElementById("popupLupajackSoon");
    if (!overlay) return;
    overlay.classList.add("active");
    overlay.setAttribute("aria-hidden", "false");
  }

  function closeHomeLupajackSoonPopup() {
    const overlay = document.getElementById("popupLupajackSoon");
    if (!overlay) return;
    overlay.classList.remove("active");
    overlay.setAttribute("aria-hidden", "true");
  }

  function initHomeLupajackSoonPopup() {
    const overlay = document.getElementById("popupLupajackSoon");
    if (!overlay || overlay.dataset.homeLupajackBound === "1") return;
    overlay.dataset.homeLupajackBound = "1";

    [
      document.getElementById("homeLupajackExploreBtn"),
      document.getElementById("homeMateAsadoExploreBtn"),
    ]
      .filter(Boolean)
      .forEach((btn) => {
        btn.addEventListener("click", (e) => {
          e.preventDefault();
          openHomeLupajackSoonPopup();
        });
      });

    const closeX = document.getElementById("closeLupajackSoonPopup");
    if (closeX) closeX.addEventListener("click", closeHomeLupajackSoonPopup);

    const okBtn = document.getElementById("lupajackSoonPopupOk");
    if (okBtn) okBtn.addEventListener("click", closeHomeLupajackSoonPopup);

    overlay.addEventListener("click", (e) => {
      if (e.target === overlay) closeHomeLupajackSoonPopup();
    });

    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && overlay.classList.contains("active")) closeHomeLupajackSoonPopup();
    });
  }

  window.openHomeLupajackSoonPopup = openHomeLupajackSoonPopup;

  function bindLanguageSwitcher() {
    if (window.__SACRAMENTO_LANG_SWITCHER_BOUND__) return;
    window.__SACRAMENTO_LANG_SWITCHER_BOUND__ = true;

    document.addEventListener("click", (event) => {
      const button = event.target.closest(".lang-btn");
      if (!button) return;
      const lang = button.dataset.lang;
      if (lang !== "en" && lang !== "es" && lang !== "pt") return;
      event.preventDefault();
      if (typeof window.sacramentoMarkLanguageChosen === "function") {
        window.sacramentoMarkLanguageChosen();
      }
      document.documentElement.classList.remove("sacramento-awaiting-lang");
      document.documentElement.classList.add("sacramento-lang-ready");
      setLanguage(lang);
    });
  }

  let homePageBooted = false;

  function initGalleryLightbox() {
    const lightbox = document.getElementById("lightbox");
    const lightboxImg = document.getElementById("lightboxImg");
    if (!lightbox || !lightboxImg || lightbox.dataset.sacramentoBound === "1") return;
    lightbox.dataset.sacramentoBound = "1";

    const mediaEls = document.querySelectorAll(
      ".gallery-grid > img, .gallery-grid > .gallery-video-thumb, .gallery-grid > video"
    );
    const closeBtn = document.getElementById("closeLightbox");
    const prevBtn = document.getElementById("prevBtn");
    const nextBtn = document.getElementById("nextBtn");

    let currentIndex = 0;
    const mediaArray = Array.from(mediaEls);
    let lightboxVideo = null;

    const ensureLightboxVideo = () => {
      if (!lightboxVideo) {
        lightboxVideo = document.createElement("video");
        lightboxVideo.className = "lightbox-inline-video";
        lightboxVideo.controls = true;
        lightboxVideo.playsInline = true;
        lightboxVideo.setAttribute("playsinline", "");
        lightboxImg.insertAdjacentElement("afterend", lightboxVideo);
      }
      return lightboxVideo;
    };

    const pauseLightboxVideo = () => {
      if (lightboxVideo) {
        lightboxVideo.pause();
        lightboxVideo.removeAttribute("src");
        lightboxVideo.innerHTML = "";
        lightboxVideo.style.display = "none";
      }
    };

    const getGalleryVideoSrc = (videoEl) => {
      const srcEl = videoEl.querySelector("source[src]");
      if (srcEl) {
        try {
          return new URL(srcEl.getAttribute("src"), window.location.href).href;
        } catch {
          return srcEl.getAttribute("src") || "";
        }
      }
      return videoEl.currentSrc || videoEl.src || "";
    };

    const videoFromGallerySlot = (slot) => {
      if (!slot) return null;
      if (slot.classList?.contains("gallery-video-thumb")) {
        return slot.querySelector("video.gallery-grid-video-el");
      }
      if (slot.tagName === "VIDEO") return slot;
      return null;
    };

    const showMedia = () => {
      if (!mediaArray.length) return;
      const slot = mediaArray[currentIndex];
      const gridVideo = videoFromGallerySlot(slot);
      if (gridVideo) {
        const v = ensureLightboxVideo();
        if (!v) return;
        lightboxImg.style.display = "none";
        v.style.display = "block";
        const src = getGalleryVideoSrc(gridVideo);
        v.innerHTML = "";
        const s = document.createElement("source");
        s.src = src;
        s.type = "video/mp4";
        v.appendChild(s);
        v.load();
      } else if (slot.tagName === "IMG") {
        pauseLightboxVideo();
        lightboxImg.style.display = "block";
        lightboxImg.src = slot.src;
      }
    };

    const closeLightbox = () => {
      pauseLightboxVideo();
      lightboxImg.style.display = "block";
      lightbox.classList.remove("active");
    };

    if (!mediaArray.length) return;

    mediaArray.forEach((el, index) => {
      const open = () => {
        currentIndex = index;
        showMedia();
        lightbox.classList.add("active");
      };
      el.style.cursor = "pointer";
      el.addEventListener("click", open);
      if (el.classList?.contains("gallery-video-thumb")) {
        el.addEventListener("keydown", (e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            open();
          }
        });
      }
    });

    function nextImage() {
      currentIndex = (currentIndex + 1) % mediaArray.length;
      showMedia();
    }

    function prevImage() {
      currentIndex = (currentIndex - 1 + mediaArray.length) % mediaArray.length;
      showMedia();
    }

    nextBtn?.addEventListener("click", (e) => {
      e.stopPropagation();
      nextImage();
    });
    prevBtn?.addEventListener("click", (e) => {
      e.stopPropagation();
      prevImage();
    });

    closeBtn?.addEventListener("click", () => {
      closeLightbox();
    });

    lightbox.addEventListener("click", (e) => {
      if (e.target === lightbox) {
        closeLightbox();
      }
    });

    document.addEventListener("keydown", (e) => {
      if (!lightbox.classList.contains("active")) return;

      if (e.key === "ArrowRight") nextImage();
      if (e.key === "ArrowLeft") prevImage();
      if (e.key === "Escape") closeLightbox();
    });
  }

  window.sacramentoInitGalleryLightbox = initGalleryLightbox;

  function bootHomePage() {
  if (homePageBooted) return;
  homePageBooted = true;

  if (window.SACRAMENTO_I18N_ONLY) {
    const savedLanguage = getInitialLanguage();
    setLanguage(savedLanguage);
    return;
  }

  injectRentBadgeInActivityHero();
  initRentPopupBehavior();

    /* ===== LANGUAGE ===== */
    const savedLanguage = getInitialLanguage();
    setLanguage(savedLanguage);
    startActivityEmojiIconObserver();

    initHomeLupajackSoonPopup();
    sacramentoInitCardReserveButtons(
      document.getElementById("experiences") || document
    );

    if (typeof window.sacramentoMountHomeCardPrices === "function") {
      window.sacramentoMountHomeCardPrices(document.getElementById("experiences"));
    }

    document.querySelectorAll(".card").forEach(card => {

        const imageContainer = card.querySelector(".card-image");
        const exploreSoonBtn = card.querySelector(
          "#homeLupajackExploreBtn, #homeMateAsadoExploreBtn"
        );
        const link = Array.from(card.querySelectorAll(".card-buttons a.btn")).find((a) => {
          const h = a.getAttribute("href");
          return h && h !== "#" && h !== "";
        });
      
        if (!imageContainer) return;
      
        imageContainer.addEventListener("click", (e) => {
      
          // 👇 evita conflicto con botones del carrusel
          if (e.target.closest(".carousel-btn")) return;
          if (e.target.closest(".discount-badge")) return;
      
          if (exploreSoonBtn) {
            e.preventDefault();
            openHomeLupajackSoonPopup();
            return;
          }

          if (!link) return;
          window.open(link.href, "_blank");
        });
      
      });
  
    initGalleryLightbox();
  
  
    /* ===== SMOOTH SCROLL ===== */
    const exploreBtn = document.getElementById("exploreBtn");
  
    if (exploreBtn) {
      exploreBtn.addEventListener("click", e => {
        e.preventDefault();
        const section = document.getElementById("experiences");
        section?.querySelectorAll(".card").forEach((card) => {
          card.style.removeProperty("display");
        });
        section?.scrollIntoView({
          behavior: "smooth"
        });
      });
    }
  
  
    /* ===== CARD BUTTON ACTIVE ===== */
    document.querySelectorAll(".card").forEach(card => {
      const buttons = card.querySelectorAll(".btn");
  
      buttons.forEach(btn => {
        btn.addEventListener("click", () => {
          buttons.forEach(b => b.classList.remove("clicked"));
          btn.classList.add("clicked");
        });
      });
    });
  
  
    /* ===== ACORDEÓN ===== */
    document.querySelectorAll(".acordeon").forEach(acc => {
      acc.addEventListener("click", function () {
        document.querySelectorAll(".acordeon").forEach(o => {
          if (o !== this) o.removeAttribute("open");
        });
      });
    });
  
  
    /* ===== VIDEO HOVER ===== */
    document.querySelectorAll(".card").forEach(card => {
      const video = card.querySelector(".card-video");
  
      if (!video) return;
  
      card.addEventListener("mouseenter", () => video.play());
      card.addEventListener("mouseleave", () => {
        video.pause();
        video.currentTime = 0;
      });
    });
  
  
    /* ===== HAMBURGER MENU ===== */
    const toggle = document.querySelector(".menu-toggle");
    const menu = document.querySelector(".hamburger-menu");
  
    if (toggle && menu) {
  
      toggle.addEventListener("click", (e) => {
        e.stopPropagation();
        menu.style.display =
          menu.style.display === "block" ? "none" : "block";
      });
  
      document.addEventListener("click", (e) => {
        if (!menu.contains(e.target) && !toggle.contains(e.target)) {
          menu.style.display = "none";
        }
      });
  
    }
  
  
    /* ===== FILTER CARDS (home: #experiences .card + data-category tokens) ===== */
    const filters = document.querySelectorAll(".hamburger-menu li");
    const experienceSection = document.getElementById("experiences");
    const cards = experienceSection
      ? experienceSection.querySelectorAll(".card")
      : document.querySelectorAll("#experiences .card");

    filters.forEach((filterEl) => {
      filterEl.addEventListener("click", () => {
        const menuEl = document.querySelector(".hamburger-menu");
        if (menuEl) menuEl.style.display = "none";

        if (experienceSection) {
          experienceSection.scrollIntoView({ behavior: "smooth", block: "start" });
        }

        const category = filterEl.dataset.filter;
        if (!category) return;

        cards.forEach((card) => {
          if (category === "all") {
            card.style.removeProperty("display");
            return;
          }

          const tokens = (card.dataset.category || "")
            .trim()
            .split(/\s+/)
            .filter(Boolean);

          if (tokens.includes(category)) {
            card.style.removeProperty("display");
          } else {
            card.style.display = "none";
          }
        });
      });
    });
  
  
    scheduleCardSeeMoreRefresh(document.getElementById("experiences") || document);
  }

  function sacramentoRunWhenDomReady(fn) {
    if (typeof document === "undefined") return;
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", fn, { once: true });
    } else {
      fn();
    }
  }

  function sacramentoRunPageI18nBoot() {
    const experiencesRoot = document.getElementById("experiences") || document;
    const isHome = Boolean(document.getElementById("experiences"));
    bindLanguageSwitcher();
    void sacramentoApplyPageIcons(document).then(() => {
      startActivityEmojiIconObserver();
    });
    scheduleCardSeeMoreRefresh(experiencesRoot);

    if (window.__SACRAMENTO_PENDING_LANG__) {
      setLanguage(window.__SACRAMENTO_PENDING_LANG__);
      delete window.__SACRAMENTO_PENDING_LANG__;
      if (!isHome) {
        initGalleryLightbox();
        return;
      }
      return;
    }

    const runBoot = () => {
      delete window.__SACRAMENTO_NEEDS_BOOT_HOME__;
      if (isHome) {
        bootHomePage();
        return;
      }
      setLanguage(getInitialLanguage());
      initGalleryLightbox();
    };

    if (
      window.__SACRAMENTO_NEEDS_BOOT_HOME__ ||
      (typeof window.sacramentoHasUserChosenLanguage === "function" &&
        window.sacramentoHasUserChosenLanguage())
    ) {
      runBoot();
      return;
    }

    document.addEventListener("sacramento:languageChosen", runBoot, { once: true });
  }

  window.sacramentoBootHomePage = bootHomePage;
  window.sacramentoRunPageI18nBoot = sacramentoRunPageI18nBoot;
  window.sacramentoApplyPageIcons = sacramentoApplyPageIcons;
  bindLanguageSwitcher();

  sacramentoRunWhenDomReady(sacramentoRunPageI18nBoot);

  document.addEventListener("sacramento:setLanguage", () => {
    sacramentoApplyPageIcons();
  });

  document.addEventListener("sacramento:languageChosen", () => {
    const experiencesRoot = document.getElementById("experiences") || document;
    sacramentoApplyPageIcons(document);
    scheduleCardSeeMoreRefresh(experiencesRoot);
  });

  window.addEventListener("load", () => {
    sacramentoApplyPageIcons(document);
  });

